     "title": "全球市场：美股收跌 存储、光通信板块逆势走强 闪迪涨超8%",
     "url": "http://stock.eastmoney.com/news/11784,202608183843639977.html",
     "time": "08-18 06:15",
     "ts": 1787004954,
